/** What a capsule's sidecar file (handoffs/<id>.json) holds. */
export type CapsuleRecord = CapsuleMeta & {
  title: string;
  tokens: number;
  sourceTokens?: number;
  turns: number;
  brief: boolean;
  jev: boolean;
  path: string;
  /** Sessions it was attached to. */
  attached: string[];
};

export function nowIso(): string {
  return new Date().toISOString();
}

export function basename(path: string): string {
  const parts = path.split('/').filter(Boolean);
  return parts[parts.length - 1] ?? path;
}

/** Whether the mod works in this chat: enabled in the config and not switched off for the chat (`/jevg chat off`). */
export function active(): boolean {
  return S.cfg.enabled && !S.chat.off;
}

/** Compaction after a pause: the setting, or switched on for this chat (`/jevg idle on`). */
export function idleCompaction(): boolean {
  return S.cfg.compaction.onReturn || S.chat.idle;
}

/** Shadow mode: decide and log, change nothing. */
export function shadow(): boolean {
  return isShadow(S.cfg, S.cwd, S.home);
}

/** The OpenRouter key, unless this project is excluded from Jev (then nothing goes out). */
export function jevKey(): string | undefined {
  return S.key && !S.chat.off && !isExcluded(S.cfg, S.cwd, S.home) ? S.key : undefined;
}

export function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * What a finished turn would have run on without the mod, for the savings report.
 * A turn the mod did not route (excluded project, no key, a /jevg fresh brief) ran
 * on its own model: `baseModel` is that model, so the report finds no saving in it
 * (an entry without any base reads as an old one and is compared with the assumed base).
 */
/** Token counts the API reported, as Claude Code passes them (`turn.step` and `turn.complete`). */
export type ModelTokens = {
  input_tokens: number;
  output_tokens: number;
  cache_read_input_tokens: number;
  cache_creation_input_tokens: number;
};

/**
 * A turn's requests on one model, summed from its steps; `long` the same for the steps whose
 * prompt was over LONG_PROMPT_TOKENS (Haiku 5.5 bills those on its long rate card).
 */
export type StepTotals = ModelTokens & { steps: number; long?: ModelTokens & { steps: number } };

/** What a turn cost on one model: one `usage` ledger entry. `steps` only when the turn ran on more than one. */
export type UsagePart = { model: string; usage: ModelTokens; long?: ModelTokens & { steps: number }; steps?: number; from: 'steps' | 'turn' };

/** Prompt tokens above which a request is counted in `long` (savings.ts LONG_PROMPT_TOKENS). */
const LONG_PROMPT = 100_000;

const zero = (): ModelTokens & { steps: number } => ({ steps: 0, input_tokens: 0, output_tokens: 0, cache_read_input_tokens: 0, cache_creation_input_tokens: 0 });

function addTokens(t: ModelTokens & { steps: number }, u: ModelTokens): void {
  t.steps++;
  t.input_tokens += u.input_tokens || 0;
  t.output_tokens += u.output_tokens || 0;
  t.cache_read_input_tokens += u.cache_read_input_tokens || 0;
  t.cache_creation_input_tokens += u.cache_creation_input_tokens || 0;
}

/** The key a running turn's step usage is kept under: a subagent's run is its own turn. */
export function stepKey(turnId: string, agentId: string | undefined): string {
  return `${agentId ?? 'main'}:${turnId}`;
}

const tokensOf = (u: ModelTokens): number => u.input_tokens + u.output_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens;

/** Adds one step's reported usage to its turn's totals (kept in `S.stepUsage`, oldest dropped past 200 turns). */
export function addStepUsage(key: string, usage: (ModelTokens & { model: string }) | null | undefined): void {
  if (!usage || typeof usage.model !== 'string') return;
  let byModel = S.stepUsage.get(key);
  if (!byModel) {
    S.stepUsage.set(key, (byModel = new Map()));
    if (S.stepUsage.size > 200) S.stepUsage.delete(S.stepUsage.keys().next().value as string);
  }
  const t: StepTotals = byModel.get(usage.model) ?? zero();
  addTokens(t, usage);
  const prompt = (usage.input_tokens || 0) + (usage.cache_read_input_tokens || 0) + (usage.cache_creation_input_tokens || 0);
  if (prompt > LONG_PROMPT) addTokens((t.long ??= zero()), usage);
  byModel.set(usage.model, t);
}

/**
 * What a finished turn cost, per model. The usage `turn.complete` carries starts over at a
 * compaction inside the turn (measured 2026-10-07: a 488-step turn with 9 window compactions
 * reported 0.4M cache-read tokens of the 72M its steps read), so the steps' own usage, summed
 * as they ran, is used instead. The turn's figure wins only when it is the larger one (a step
 * the mod did not see: a response a hook below made up). The model the turn ended on goes last.
 */
export function turnUsageParts(reported: (ModelTokens & { model: string }) | undefined, counted: Map<string, StepTotals> | undefined): UsagePart[] {
  const parts = [...(counted ?? new Map<string, StepTotals>()).entries()];
  const sum = parts.reduce((a, [, t]) => a + tokensOf(t), 0);
  if (parts.length === 0 || (reported && tokensOf(reported) > sum)) {
    if (!reported) return [];
    const { model, ...usage } = reported;
    return [{ model, usage: { input_tokens: usage.input_tokens, output_tokens: usage.output_tokens, cache_read_input_tokens: usage.cache_read_input_tokens, cache_creation_input_tokens: usage.cache_creation_input_tokens }, from: 'turn' }];
  }
  const last = reported?.model;
  parts.sort(([a], [b]) => (a === last ? 1 : 0) - (b === last ? 1 : 0));
  return parts.map(([model, { steps, long, ...usage }]) => ({ model, usage, ...(long ? { long } : {}), from: 'steps', ...(parts.length > 1 ? { steps } : {}) }));
}

/**
 * Counts a tool result toward effort escalation. `errors` is the most failures seen within the
 * `window` latest results (0: every failure of the turn), so a cluster of failures raises effort
 * and scattered ones over a long turn do not. The raise holds until `window × CALM_WINDOWS`
 * results in a row succeed, then ends: a subagent lives for thousands of steps, and one bad
 * stretch of tests kept 35k of 36k subagent steps escalated (effort changes keep the cache).
 */
export function noteToolResult(state: { errors: number; recent?: boolean[]; calm?: number }, isError: boolean, window: number): void {
  if (window <= 0) {
    if (isError) state.errors++;
    return;
  }
  const recent = (state.recent ??= []);
  recent.push(isError);
  if (recent.length > window) recent.splice(0, recent.length - window);
  state.calm = isError ? 0 : (state.calm ?? 0) + 1;
  if (state.calm >= window * CALM_WINDOWS) {
    state.errors = 0;
    return;
  }
  state.errors = Math.max(state.errors, recent.filter(Boolean).length);
}

/** Successful windows in a row that end an escalation. */
const CALM_WINDOWS = 5;

/**
 * Which of the mod's saved texts a read goes to: the compaction's archive (`pruned`), folded
 * dialog (`folded`), a trimmed output (`trim`), or Claude Code's own saved output (`tool-results`).
 * Read from the whole command: a `D=…/pruned; cat $D/x` names the folder without a slash after it.
 */
export function archiveOf(target: string, data: string): NonNullable<LedgerEntry['archive']> {
  const at = target.indexOf(`${data}/outputs/`);
  if (at >= 0) {
    const m = /^[^/\s"']+\/(pruned|folded)\b/.exec(target.slice(at + data.length + 9));
    return m ? (m[1] as 'pruned' | 'folded') : 'trim';
  }
  return target.includes('/tool-results/') ? 'tool-results' : 'other';
}

export function usageBase(
  agentId: string | undefined,
  ranModel: string,
): Pick<LedgerEntry, 'baseModel' | 'baseEffort' | 'effort' | 'steps' | 'escalated' | 'unrouted'> {
  if (agentId !== undefined) {
    const sub = S.subs.get(agentId);
    return sub
      ? { baseModel: sub.baseModel ?? ranModel, baseEffort: sub.baseEffort, effort: sub.effort, steps: sub.steps || undefined, escalated: sub.escalated || undefined }
      : { baseModel: ranModel, unrouted: true };
  }
  const turn = S.turn;
  return turn
    ? { baseModel: turn.baseModel ?? ranModel, baseEffort: turn.baseEffort, effort: turn.sentEffort, steps: turn.steps || undefined, escalated: turn.escalated || undefined }
    : { baseModel: ranModel, unrouted: true };
}

/**
 * Folds a finished main turn into the session's running turn profile. The profile
 * is what every later turn costs (switchEconomics multiplies it by the turns ahead),
 * so a turn that re-wrote the whole context adds its output only: one cold return
 * at 150k would otherwise lift the cache write fourfold and make a downgrade on a
 * warm cache look worth it.
 */
export function learnTurn(usage: { output_tokens: number; cache_creation_input_tokens: number }, rewroteCache = false): void {
  const prev = S.route.turnProfile ?? (rewroteCache ? DEFAULT_TURN : undefined);
  const w = 0.3;
  const write = rewroteCache ? prev!.cacheWrite : usage.cache_creation_input_tokens;
  // One very long turn (a 159-step one wrote 404k) moves the profile at most to 3× where it was,
  // so it cannot make every switch look worth it for the turns after.
  const sample = (value: number, was: number): number => Math.min(value, was * 3);
  S.route.turnProfile = prev
    ? {
        output: Math.round(prev.output * (1 - w) + sample(usage.output_tokens, prev.output) * w),
        cacheWrite: Math.round(prev.cacheWrite * (1 - w) + sample(write, prev.cacheWrite) * w),
      }
    : { output: usage.output_tokens, cacheWrite: usage.cache_creation_input_tokens };
}

export function statusText(model: string, effort: string | undefined, pressureText: string): string {
  return `jev ▸ ${displayModel(model)}${effort ? `·${effort}` : ''}${pressureText ? ` │ ${pressureText}` : ''}`;
}

export type SpawnPlan = {
  rate: Rate;
  prompt: string;
  model?: string;
  decision?: Decision;
  agent?: AgentRecord;
  created: boolean;
  signals?: Signals;
  pressure: Pressure;
  jevMs?: number;
  jevCost?: number;
};

/** What identifies a spawn's task in its subagent's first message. */
export function promptKey(prompt: string): string {
  return prompt.trim().slice(0, 160);
}

// ------------------------------------------------------------- trimming --

export function outputsDir(): string {
  return `${S.data}/outputs/${S.session}`;
}

/** The calls a compaction's decisions drop or truncate. */
export function prunedOf(original: readonly Message[], decisions: readonly CallDecision[]): PrunedCall[] {
  const calls = collectToolCalls(original, Math.max(0, Math.floor(S.cfg.compaction.preserveRecentMessages)));
  return prunedCalls(original, decisions, calls);
}

/** Remembers what a main-loop compaction pruned, to notice when the model runs it again. */
export function rememberPruned(pruned: readonly PrunedCall[]): void {
  const keys = { ...(S.route.pruned ?? {}) };
  for (const call of pruned) {
    const key = rerunKey(call.tool, call.input);
    if (key) keys[key] = callLabel(call.tool, call.input, 160);
  }
  const entries = Object.entries(keys);
  S.route.pruned = Object.fromEntries(entries.slice(-500));
}

/** The text of a tool_result block, or undefined when it holds media (left alone). */
export function resultText(block: Record<string, unknown>): string | undefined {
  const content = block.content;
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return undefined;
  const parts: string[] = [];
  for (const item of content as Record<string, unknown>[]) {
    if (item.type !== 'text' || typeof item.text !== 'string') return undefined;
    parts.push(item.text);
  }
  return parts.join('\n');
}

// ------------------------------------------------------------- handoff --

export function handoffDir(): string {
  return `${S.data}/handoffs`;
}

export function kTokens(tokens: number | undefined): string {
  return tokens === undefined ? '?' : `${Math.round(tokens / 100) / 10}k`;
}

/** The main loop sent a request recently enough that its prompt cache is still warm. */
export function cacheWarm(): boolean {
  return S.lastMainStepAt !== undefined && Date.now() - S.lastMainStepAt < (S.cfg.router.cacheTtlMinutes - 2) * 60_000;
}

/** A message of the mod in the language of this chat: `L('по-русски', 'in English')`. */
export const L = (ru: string, en: string): string => (S.lang === 'ru' ? ru : en);

files.hooks/lib/compaction/state.ts:
// Vendored from tamaratran/fast-jev-compaction (MIT, see ./LICENSE) at commit e3f262a.
// Changes by jev-governor (transport is supplied through JevAsker):
// - result previews: Jev sees the start and end of each tool output
//   (`resultPreviewChars`, 0 = upstream behaviour), not only its length;
// - `limitPruning`: puts calls back until at most `maxPruneRatio` is removed.

import type {
  CompactionState,
  FittedState,
  HistoryEntry,
  HistoryToolCall,
  Message,
  ResolvedCompactOptions,
  ToolCall,
  ToolResult,
} from './types.ts';

export const STATE_CONTEXT =
  'A coding assistant conversation is being compacted to free context. `history` is the whole conversation so far, oldest first; tool outputs are replaced by a short `result` note (status, size and, where room allows, the start and end of the output) and long texts may be abridged. Each question asks whether one tool call, or the full output of that call, still needs to stay in the history verbatim. Whatever is not kept is deleted permanently, but the assistant can always re-run a tool or re-read a file.';

/** Successive caps on the serialised tool input included per call. */
const INPUT_CHARS = [1000, 200, 60] as const;
const TEXT_HEAD = 400;
const TEXT_TAIL = 150;

const TOKEN_PIECES = /[A-Za-z]+|\d+|[^\sA-Za-z\d]/g;

/**
 * Estimates tokens without a tokenizer: a word costs one token per six
 * letters, a digit half a token, any other symbol nine tenths. Calibrated
 * against the usage Jev reports for real transcripts, where it lands 2–18%
 * above the true count; a plain characters-per-token ratio undercounts the
 * JSON-heavy states by up to 40%.
 */
export function estimateTokens(text: string): number {
  let tokens = 0;
  for (const [piece] of text.matchAll(TOKEN_PIECES)) {
    const first = piece.charCodeAt(0);
    if (first >= 48 && first <= 57) tokens += piece.length / 2;
    else if ((first >= 65 && first <= 90) || (first >= 97 && first <= 122)) {
      tokens += 1 + Math.floor((piece.length - 1) / 6);
    } else tokens += 0.9;
  }
  return Math.ceil(tokens);
}

export function truncate(text: string, limit: number): string {
  return text.length <= limit ? text : `${text.slice(0, Math.max(0, limit - 1))}…`;
}

function abridge(text: string, head: number, tail: number): string {
  if (text.length <= head + tail + 40) return text;
  const omitted = text.length - head - tail;
  return `${text.slice(0, head)}\n[… ${omitted} chars omitted …]\n${text.slice(-tail)}`;
}

export function isPinned(
  index: number,
  total: number,
  preserveRecentMessages: number,
): boolean {
  return index === 0 || index >= total - preserveRecentMessages;
}

/**
 * Pairs every tool_use with its tool_result by `tool_use_id`. Calls without a
 * result are not candidates (there is nothing to drop yet).
 */
export function collectToolCalls(
  messages: readonly Message[],
  preserveRecentMessages: number,
): ToolCall[] {
  const results = new Map<string, { index: number; result: ToolResult }>();
  messages.forEach((message, index) => {
    for (const result of message.toolResults ?? []) {
      results.set(result.tool_use_id, { index, result });
    }
  });
  const calls: ToolCall[] = [];
  messages.forEach((message, callIndex) => {
    for (const tool of message.toolUses) {
      const found = results.get(tool.tool_use_id);
      if (!found) continue;
      calls.push({
        id: `t${calls.length + 1}`,
        tool_use_id: tool.tool_use_id,
        tool: tool.tool,
        input: tool.input,
        callIndex,
        resultIndex: found.index,
        resultChars: found.result.text.length,
        result: found.result.text,
        isError: found.result.isError ?? false,
        pinned:
          isPinned(callIndex, messages.length, preserveRecentMessages) ||
          isPinned(found.index, messages.length, preserveRecentMessages),
      });
    }
  });
  return calls;
}

function inputText(input: Record<string, unknown>, limit: number): string {
  let json = '';
  try {
    json = JSON.stringify(input);
  } catch {
    json = '[unserializable input]';
  }
  return truncate(json, limit);
}

/** Characters past a preview's cut that `resultNote`'s filter also sees. */
const PREVIEW_MARGIN = 80;

/** Status and size of a result, with its start and end when `previewChars` > 0. */
export function resultNote(
  call: Pick<ToolCall, 'isError' | 'resultChars' | 'result'>,
  previewChars = 0,
  filter?: (text: string) => string,
): string {
  const status = call.isError ? 'error' : 'ok';
  const raw = previewChars > 0 ? (call.result ?? '') : '';
  if (!raw.trim()) return `${status}, ${call.resultChars} chars (omitted)`;
  const flat = (text: string): string => (filter ? filter(text) : text).replace(/\s+/g, ' ').trim();
  // The filter sees a margin past each cut: a secret across the cut is whole when it is replaced.
  const reach = previewChars + PREVIEW_MARGIN;
  const whole = raw.length <= reach * 2;
  const head = flat(whole ? raw : raw.slice(0, reach));
  if (whole && head.length <= previewChars * 2 + 20) return `${status}, ${call.resultChars} chars: ${head}`;
  const tail = whole ? head : flat(raw.slice(-reach));
  return `${status}, ${call.resultChars} chars: ${head.slice(0, previewChars)} […] ${tail.slice(-previewChars)}`;
}

/** One call as a single line, for when the structured form is too costly. */
function compactCall(call: ToolCall): string {
  const input = Object.entries(call.input)
    .map(([key, value]) => {
      const text = typeof value === 'string' ? value : inputText({ [key]: value }, 200);
      return `${key}=${text.replace(/\s+/g, ' ')}`;
    })
    .join(' ');
  return `${call.id} ${call.tool} ${truncate(input, INPUT_CHARS[2])} → ${
    call.isError ? 'error' : 'ok'
  } ${call.resultChars}ch`;
}

/**
 * Folds runs of adjacent call-only entries into one entry each, so the
 * per-entry envelope is paid once per run; the call lines keep their ids.
 */
function mergeCallRuns(history: readonly HistoryEntry[], pinned: (e: HistoryEntry) => boolean): HistoryEntry[] {
  const merged: HistoryEntry[] = [];
  for (const entry of history) {
    const previous = merged[merged.length - 1];
    const foldable = (e: HistoryEntry): boolean =>
      !pinned(e) && e.text.length === 0 && typeof e.tool_calls?.[0] === 'string';
    if (previous && foldable(previous) && foldable(entry) && previous.role === entry.role) {
      previous.tool_calls = [...(previous.tool_calls as string[]), ...(entry.tool_calls as string[])];
      continue;
    }
    merged.push({ ...entry });
  }
  return merged;
}

function callsByMessage(calls: readonly ToolCall[]): Map<number, ToolCall[]> {
  const byMessage = new Map<number, ToolCall[]>();
  for (const call of calls) {
    const list = byMessage.get(call.callIndex) ?? [];
    list.push(call);
    byMessage.set(call.callIndex, list);
  }
  return byMessage;
}

function historyEntries(
  messages: readonly Message[],
  calls: readonly ToolCall[],
  inputChars: number,
  previewChars: number,
  filter?: (text: string) => string,
): HistoryEntry[] {
  const byMessage = callsByMessage(calls);
  const entries: HistoryEntry[] = [];
  messages.forEach((message, i) => {
    const toolCalls = (byMessage.get(i) ?? []).map((call) => ({
      id: call.id,
      tool: call.tool,
      input: inputText(call.input, inputChars),
      result: resultNote(call, previewChars, filter),
    }));
    if (message.text.trim().length === 0 && toolCalls.length === 0) return;
    const entry: HistoryEntry = { i, role: message.role, text: message.text };
    if (toolCalls.length > 0) entry.tool_calls = toolCalls;
    entries.push(entry);
  });
  return entries;
}

/** The last three user prompts, as the default `goal`. */
export function goalFromMessages(messages: readonly Message[]): string {
  return messages
    .filter(
      (message) =>
        message.role === 'user' &&
        message.text.trim().length > 0 &&
        (message.toolResults ?? []).length === 0,
    )
    .slice(-3)
    .map((message) => truncate(message.text, 500))
    .join('\n');
}

/**
 * Builds the Jev state from the whole conversation and shrinks it in stages
 * until it fits `maxStateTokens`: tool inputs are truncated, then the result
 * previews are left out oldest-first (pinned messages last), then long texts
 * are abridged oldest-first (pinned messages last), then old messages collapse
 * to a one-line note, then old tool calls shrink to one line each, then old
 * messages that carry no call are left out, then runs of old call-only
 * messages are folded into one entry. Throws when even that is too big.
 */
export function fitState(
  messages: readonly Message[],
  calls: readonly ToolCall[],
  options: Pick<ResolvedCompactOptions, 'maxStateTokens' | 'preserveRecentMessages' | 'goal'> &
    Partial<Pick<ResolvedCompactOptions, 'resultPreviewChars' | 'previewFilter'>>,
): FittedState {
  const previewChars = Math.max(0, Math.floor(options.resultPreviewChars ?? 0));
  const goal = options.goal || goalFromMessages(messages);
  const stateOf = (history: HistoryEntry[]): CompactionState => ({
    context: STATE_CONTEXT,
    goal,
    history,
  });
  const entryTokens = (entry: HistoryEntry): number => estimateTokens(JSON.stringify(entry)) + 1;
  const baseTokens = estimateTokens(JSON.stringify(stateOf([])));
  const fitted = (history: HistoryEntry[], tokens: number, stage: string): FittedState => ({
    state: stateOf(history),
    tokens,
    stage,
  });

  let history: HistoryEntry[] = [];
  let perEntry: number[] = [];
  let tokens = 0;
  const rebuild = (inputChars: number, preview = previewChars): void => {
    history = historyEntries(messages, calls, inputChars, preview, options.previewFilter);
    perEntry = history.map(entryTokens);
    tokens = baseTokens + perEntry.reduce((sum, n) => sum + n, 0);
  };
  const fits = (): boolean => tokens <= options.maxStateTokens;
  const shrink = (index: number, change: (entry: HistoryEntry) => void): void => {
    const entry = history[index];
    if (!entry) return;
    change(entry);
    const now = entryTokens(entry);
    tokens += now - (perEntry[index] ?? 0);
    perEntry[index] = now;
  };

  rebuild(INPUT_CHARS[0]);
  if (fits()) return fitted(history, tokens, 'full');
  rebuild(INPUT_CHARS[1]);
  if (fits()) return fitted(history, tokens, `inputs<=${INPUT_CHARS[1]}`);

  const pinned = (entry: HistoryEntry): boolean =>
    isPinned(entry.i, messages.length, options.preserveRecentMessages);
  const indices = history.map((_, index) => index);
  const order = [
    ...indices.filter((index) => !pinned(history[index]!)),
    ...indices.filter((index) => pinned(history[index]!)),
  ];

  // Previews go before inputs are cut to a few dozen characters: a call's file
  // or command tells Jev more than a glimpse of its output.
  if (previewChars > 0) {
    const byId = new Map(calls.map((call) => [call.id, call]));
    for (const index of order) {
      const entry = history[index]!;
      if (!entry.tool_calls || typeof entry.tool_calls[0] === 'string') continue;
      shrink(index, (e) => {
        e.tool_calls = (e.tool_calls as HistoryToolCall[]).map((c) => {
          const call = byId.get(c.id);
          return call ? { ...c, result: resultNote(call) } : c;
        });
      });
      if (fits()) return fitted(history, tokens, 'previews left out');
    }
  }
  rebuild(INPUT_CHARS[2], 0);
  if (fits()) return fitted(history, tokens, `inputs<=${INPUT_CHARS[2]}`);

  for (const index of order) {
    const entry = history[index]!;
    if (entry.text.length <= TEXT_HEAD + TEXT_TAIL + 40) continue;
    shrink(index, (e) => {
      e.text = abridge(e.text, TEXT_HEAD, TEXT_TAIL);
    });
    if (fits()) return fitted(history, tokens, 'texts abridged');
  }

  for (const index of order) {
    const entry = history[index]!;
    if (pinned(entry) || entry.text.length === 0) continue;
    const original = messages[entry.i]?.text.length ?? entry.text.length;
    shrink(index, (e) => {
      e.text = `[… ${original} chars omitted …]`;
    });
    if (fits()) return fitted(history, tokens, 'old messages collapsed');
  }

  const byMessage = callsByMessage(calls);
  for (const index of order) {
    const entry = history[index]!;
    const own = byMessage.get(entry.i);
    if (pinned(entry) || !own) continue;
    shrink(index, (e) => {
      e.tool_calls = own.map(compactCall);
    });
    if (fits()) return fitted(history, tokens, 'old calls compacted');
  }

  const left = new Set<number>();
  for (const index of order) {
    const entry = history[index]!;
    if (pinned(entry) || entry.tool_calls) continue;
    left.add(index);
    tokens -= perEntry[index] ?? 0;
    if (fits()) {
      return fitted(
        history.filter((_, i) => !left.has(i)),
        tokens,
        'old messages left out',
      );
    }
  }

  history = mergeCallRuns(
    history.filter((_, i) => !left.has(i)),
    pinned,
  );
  perEntry = history.map(entryTokens);
  tokens = baseTokens + perEntry.reduce((sum, n) => sum + n, 0);
  if (fits()) return fitted(history, tokens, 'old calls merged');

  throw new Error(
    `history too large for Jev (~${tokens} tokens after truncation, limit ${options.maxStateTokens})`,
  );
}

